BEGIN;
-- Biblioteca Inclusiva · Ensino Religioso do 5º ano completo.
-- Abordagem não confessional: estudar tradições não exige crença, prática ou exposição pessoal.
WITH lessons(code,source_key,title,goal) AS (VALUES
('EF05ER01','src/escola-brilha/curso-v4/ensino-religioso-5ano/unidade-1/aula-01-acontecimentos-sagrados.ts','Acontecimentos sagrados e memória','Identificar acontecimentos sagrados de diferentes culturas e tradições como parte da preservação da memória, sem hierarquizar crenças.'),
('EF05ER02','src/escola-brilha/curso-v4/ensino-religioso-5ano/aulas-corrigidas.ts','Mitos de criação em diferentes culturas','Identificar mitos de criação em diferentes culturas, distinguindo narrativa religiosa ou cultural de explicação científica sem chamar mito de mentira.'),
('EF05ER03','src/escola-brilha/curso-v4/ensino-religioso-5ano/aulas-corrigidas.ts','Funções e mensagens dos mitos de criação','Reconhecer concepções de mundo, valores, relações e responsabilidades comunicadas por mitos de criação.'),
('EF05ER04','src/escola-brilha/curso-v4/ensino-religioso-5ano/unidade-4/aula-01-tradicao-oral.ts','Tradição oral e memória religiosa','Reconhecer a importância da tradição oral para preservar memórias e conhecimentos religiosos e culturais.'),
('EF05ER05','src/escola-brilha/curso-v4/ensino-religioso-5ano/unidade-5/aula-01-oralidade-culturas.ts','Oralidade em culturas diversas','Identificar elementos da tradição oral em culturas indígenas, afro-brasileiras e dos povos Rom, Calon e Sinti com linguagem respeitosa e contextualizada.'),
('EF05ER06','src/escola-brilha/curso-v4/ensino-religioso-5ano/aulas-corrigidas.ts','Sábios, anciãos e memória coletiva','Identificar o papel de pessoas mais velhas, sábios e lideranças reconhecidas pelas comunidades na transmissão responsável de memórias.'),
('EF05ER07','src/escola-brilha/curso-v4/ensino-religioso-5ano/aulas-corrigidas.ts','Ensinamentos em textos orais','Reconhecer ensinamentos sobre modos de ser e viver em textos orais sem transformar o conteúdo estudado em regra religiosa obrigatória.')
)
INSERT INTO public.teacher_inclusive_lessons (source_lesson_key,source_version,codigo_bncc,title,school_stage,school_year,subject,knowledge_object,learning_goal,supported_profiles,teacher_pages,student_pages,answer_key,accessibility,source_fidelity_checked,pedagogical_reviewed,technical_reviewed,status,source_route)
SELECT source_key,'audit-2026-09-04',code,title,'fundamental_1','5º Ano','Ensino Religioso',title,goal,ARRAY['tea','tdah','dislexia','deficiencia_intelectual','comunicacao','motora_escrita','sensorial_auditiva','sensorial_visual'],
jsonb_build_array(jsonb_build_object('title','Guia inclusivo de Ensino Religioso — '||code,'purpose',goal,'sections',jsonb_build_array(
 jsonb_build_object('heading','Abordagem não confessional','content',jsonb_build_array('Apresente o conteúdo como conhecimento histórico, cultural e religioso: estudar não significa acreditar, aderir, concordar ou praticar.','Não conduza oração, rito, oferenda, canto, recitação, dramatização de prática sagrada, uso de vestimenta ritual ou representação de divindade. Sempre ofereça atividade neutra equivalente.','Nunca peça que estudante revele religião, ausência de religião, tradição familiar, objeto sagrado, fotografia, experiência íntima ou participação comunitária.')),
 jsonb_build_object('heading','Investigação respeitosa','content',jsonb_build_array('Use excertos breves, paráfrases, imagens autorizadas e fontes produzidas ou validadas pelas próprias comunidades; preserve autoria, contexto, diversidade interna e contemporaneidade.','Diferencie narrativa religiosa ou cultural e explicação científica por finalidade e método. Mito não significa mentira, e nenhuma tradição deve ser tratada como superior, exótica ou homogênea.','Ao abordar povos indígenas, culturas afro-brasileiras e povos Rom, Calon e Sinti, use os nomes específicos disponíveis, reconheça protagonismo atual e não peça imitação de sotaque, canto, rito, liderança ou identidade.')),
 jsonb_build_object('heading','Acesso, escolha e privacidade','content',jsonb_build_array('Antecipe vocabulário e sequência; ofereça leitura segmentada, descrição de imagem, áudio regulável, legenda, transcrição, pausa planejada, cartões e modelo resolvido.','Aceite apontar, selecionar, ordenar cartões, completar quadro comparativo, comunicação alternativa, digitação, escrita, fala opcional ou áudio privado.','Evite exposição individual. Compare apenas materiais fornecidos pelo professor e permita recusa ou troca de qualquer atividade sem redução da avaliação.')),
 jsonb_build_object('heading','Critério','content','Identifica e relaciona pelo menos quatro de cinco elementos da habilidade usando evidências do material, linguagem respeitosa e o modo de resposta acessível escolhido.')))),
jsonb_build_array(jsonb_build_object('title','1. Observar e contextualizar','instruction','Localize autoria, comunidade, tempo, lugar, gênero e finalidade no material fornecido.','activity','Associe quatro cartões de contexto a trechos, imagens ou resumos sobre '||lower(title)||'.','support','Leitura fácil, pictogramas, fonte ampliada, contraste, descrição de imagem, áudio com legenda e transcrição.'),jsonb_build_object('title','2. Comparar sem hierarquizar','instruction','Organize semelhanças e diferenças sem decidir qual tradição seria melhor ou verdadeira.','activity','Complete quadro com contexto, forma de transmissão, mensagem, evidência e cuidado de linguagem.','support','Modelo resolvido, banco de palavras, cartões móveis, pista gradual e mediador de comunicação.'),jsonb_build_object('title','3. Explicar com respeito','instruction','Escolha uma evidência e explique a relação com a habilidade, sem falar sobre crença pessoal.','activity','Produza resposta curta, sequência visual, mapa de conceitos ou áudio privado e revise termos respeitosos.','support','Apontar, selecionar, comunicação alternativa, digitar, escrever, fala opcional ou tecnologia assistiva.')),
jsonb_build_array(jsonb_build_object('page',1,'answer','Identifica contexto e evidência pertinentes sem atribuir crença ao estudante ou à comunidade inteira.'),jsonb_build_object('page',2,'answer','Compara elementos por finalidade, mensagem e contexto sem hierarquização.'),jsonb_build_object('page',3,'answer','Explicação coerente, respeitosa e sustentada pelo material.','teacher_note','Registre estratégia e apoio eficaz; não registre religião, não religião, tradição familiar, voz, fotografia ou experiência pessoal.')),
jsonb_build_object('response_modes',jsonb_build_array('pointing','selection','sequencing_cards','comparison_chart','aac','oral_optional','private_audio','typing','writing','assistive_technology'),'routine','adjustable','one_instruction_at_a_time',true,'read_aloud',true,'captions',true,'transcript',true,'large_text',true,'segmented_text',true,'image_description',true,'visual_schedule',true,'planned_pause',true,'audio_replay',true,'playback_speed_control',true,'volume_control',true,'no_forced_speaking',true,'no_forced_prayer',true,'no_forced_ritual',true,'no_forced_recitation',true,'no_sacred_practice_simulation',true,'neutral_equivalent_activity',true,'opt_out_without_penalty',true,'non_confessional',true,'no_belief_disclosure',true,'no_nonbelief_disclosure',true,'no_family_religion_disclosure',true,'no_sacred_object_request',true,'no_personal_experience_request',true,'privacy_preserving',true,'compare_provided_materials_only',true,'no_belief_hierarchy',true,'myth_is_not_lie',true,'science_religion_method_distinction',true,'community_authority',true,'indigenous_afro_brazilian_romani_dignity',true,'no_identity_impersonation',true,'copyright_respect',true,'mobility_vision_hearing_inclusive',true,'print','grayscale-safe'),true,true,true,'published','/escola-brilha/curso-v4/ensino-religioso-5ano/'||lower(code) FROM lessons
ON CONFLICT (source_lesson_key,codigo_bncc) DO UPDATE SET source_version=EXCLUDED.source_version,title=EXCLUDED.title,school_stage=EXCLUDED.school_stage,school_year=EXCLUDED.school_year,subject=EXCLUDED.subject,knowledge_object=EXCLUDED.knowledge_object,learning_goal=EXCLUDED.learning_goal,supported_profiles=EXCLUDED.supported_profiles,teacher_pages=EXCLUDED.teacher_pages,student_pages=EXCLUDED.student_pages,answer_key=EXCLUDED.answer_key,accessibility=EXCLUDED.accessibility,source_fidelity_checked=EXCLUDED.source_fidelity_checked,pedagogical_reviewed=EXCLUDED.pedagogical_reviewed,technical_reviewed=EXCLUDED.technical_reviewed,status=EXCLUDED.status,source_route=EXCLUDED.source_route,updated_at=now();
-- Biblioteca Inclusiva · Ensino Religioso do 6º ano completo.
-- Abordagem não confessional, com estudo contextualizado de textos, narrativas, ritos e símbolos.
WITH lessons(code,source_key,title,goal) AS (VALUES
('EF06ER01','src/escola-brilha/curso-v4/ensino-religioso-6ano/unidade-1/aula-01-tradicao-escrita.ts','Tradição escrita e memória','Reconhecer o papel da tradição escrita no registro e na preservação de memórias, acontecimentos e ensinamentos religiosos.'),
('EF06ER02','src/escola-brilha/curso-v4/ensino-religioso-6ano/unidade-2/aula-01-diversidade-textos.ts','Diversidade de textos religiosos','Reconhecer e valorizar a diversidade de textos religiosos escritos e tradições orais, considerando autoria, comunidade e contexto.'),
('EF06ER03','src/escola-brilha/curso-v4/ensino-religioso-6ano/unidade-3/aula-01-ensinamentos-viver.ts','Ensinamentos sobre modos de viver','Reconhecer em textos religiosos ensinamentos relacionados a modos de ser, conviver e cuidar, sem convertê-los em regra obrigatória para a turma.'),
('EF06ER04','src/escola-brilha/curso-v4/ensino-religioso-6ano/unidade-4/aula-01-usos-diversos.ts','Diferentes usos dos textos religiosos','Identificar diferentes usos de textos religiosos pelas comunidades, estudando finalidade e contexto sem executar práticas sagradas.'),
('EF06ER05','src/escola-brilha/curso-v4/ensino-religioso-6ano/unidade-5/aula-01-interpretacao-textos.ts','Interpretação dos textos religiosos','Discutir como diferentes tradições e lideranças interpretam seus textos, reconhecendo diversidade interna e autoridade comunitária.'),
('EF06ER06','src/escola-brilha/curso-v4/ensino-religioso-6ano/unidade-6/aula-01-mitos-ritos-textos.ts','Mitos, ritos, símbolos e textos','Reconhecer relações entre narrativas, textos, ritos e símbolos em diferentes tradições por análise documental não imersiva.'),
('EF06ER07','src/escola-brilha/curso-v4/ensino-religioso-6ano/unidade-7/aula-01-relacao-mito-rito-simbolo.ts','Relações entre mito, rito e símbolo','Explicar como mito, rito e símbolo se relacionam em práticas celebrativas sem reproduzir ou dramatizar a prática estudada.')
)
INSERT INTO public.teacher_inclusive_lessons (source_lesson_key,source_version,codigo_bncc,title,school_stage,school_year,subject,knowledge_object,learning_goal,supported_profiles,teacher_pages,student_pages,answer_key,accessibility,source_fidelity_checked,pedagogical_reviewed,technical_reviewed,status,source_route)
SELECT source_key,'audit-2026-09-04',code,title,'fundamental_2','6º Ano','Ensino Religioso',title,goal,ARRAY['tea','tdah','dislexia','deficiencia_intelectual','comunicacao','motora_escrita','sensorial_auditiva','sensorial_visual'],
jsonb_build_array(jsonb_build_object('title','Guia inclusivo de Ensino Religioso — '||code,'purpose',goal,'sections',jsonb_build_array(
 jsonb_build_object('heading','Ensino não confessional','content',jsonb_build_array('Explique que a aula estuda textos, narrativas, símbolos e práticas como manifestações religiosas e culturais; conhecer não significa acreditar, aderir, concordar ou praticar.','Não conduza oração, recitação devocional, meditação religiosa, rito, canto, dança, gesto, dramatização, oferenda, uso ritual de objeto ou representação de divindade. Ofereça análise documental neutra.','Não peça religião, não religião, tradição familiar, texto sagrado pessoal, local frequentado, fotografia, experiência íntima ou justificativa de crença. Recusa e alternativa neutra não reduzem a avaliação.')),
 jsonb_build_object('heading','Fontes e interpretação','content',jsonb_build_array('Utilize excertos breves, paráfrases e imagens autorizadas, licenciadas ou em domínio público; informe fonte, tradução, autoria quando conhecida, comunidade, gênero, época e finalidade. Não reproduza obra extensa.','Diferencie descrição, interpretação acadêmica e interpretação interna da tradição. Apresente diversidade dentro de cada comunidade e não transforme uma liderança em porta-voz de todas as pessoas.','Mito não significa mentira. Compare função, estrutura e contexto sem hierarquizar tradições nem usar textos religiosos para validar ou invalidar explicações científicas.')),
 jsonb_build_object('heading','Análise acessível e respeitosa','content',jsonb_build_array('Antecipe vocabulário potencialmente desconhecido; use organizador visual com texto ou narrativa, contexto, ensinamento, uso, símbolo e evidência.','Quando houver rito ou celebração, analise material fornecido por descrição, fotografia autorizada, diagrama ou vídeo com legenda e transcrição; não peça encenação, imitação, vestimenta ou manuseio de objeto sagrado.','Aceite apontar, selecionar, ordenar cartões, comunicação alternativa, quadro comparativo, digitação, escrita, fala opcional ou áudio privado; nunca obrigue leitura pública.')),
 jsonb_build_object('heading','Critério','content','Identifica e relaciona quatro de cinco elementos da habilidade com evidência, contexto, linguagem respeitosa e o modo acessível escolhido.')))),
jsonb_build_array(jsonb_build_object('title','1. Ler o contexto','instruction','Identifique fonte, comunidade, gênero, época, finalidade e modo de transmissão no material fornecido.','activity','Associe cartões de contexto a excertos breves, paráfrases, descrições ou imagens sobre '||lower(title)||'.','support','Texto segmentado, leitura fácil, glossário visual, fonte ampliada, descrição de imagem, áudio regulável, legenda e transcrição.'),jsonb_build_object('title','2. Analisar relações','instruction','Relacione narrativa ou texto, ensinamento, uso, rito e símbolo somente quando os elementos estiverem documentados.','activity','Complete quadro comparativo e destaque uma evidência para cada relação, sem hierarquizar tradições.','support','Modelo resolvido, cartões móveis, código por forma e rótulo, pista gradual, mediador e tempo ampliado.'),jsonb_build_object('title','3. Explicar sem praticar','instruction','Explique a relação observada como estudo cultural e religioso, sem reproduzir a prática.','activity','Produza mapa de conceitos, sequência visual, resposta curta ou áudio privado e revise fonte, contexto e termos.','support','Apontar, selecionar, comunicação alternativa, digitar, escrever, fala opcional ou tecnologia assistiva.')),
jsonb_build_array(jsonb_build_object('page',1,'answer','Identifica fonte, comunidade, gênero, época e finalidade sem inferir a crença do estudante.'),jsonb_build_object('page',2,'answer','Relaciona elementos documentados e reconhece interpretações possíveis sem generalização ou hierarquia.'),jsonb_build_object('page',3,'answer','Explica com evidência, contexto e linguagem respeitosa sem executar prática religiosa.','teacher_note','Registre somente estratégia e apoio eficaz; não registre crença, não crença, voz, imagem, comunidade frequentada ou dado familiar.')),
jsonb_build_object('response_modes',jsonb_build_array('pointing','selection','sequencing_cards','concept_map','comparison_chart','aac','oral_optional','private_audio','typing','writing','assistive_technology'),'routine','adjustable','one_instruction_at_a_time',true,'read_aloud',true,'captions',true,'transcript',true,'large_text',true,'segmented_text',true,'image_description',true,'visual_glossary',true,'visual_schedule',true,'planned_pause',true,'audio_replay',true,'playback_speed_control',true,'volume_control',true,'no_forced_speaking',true,'no_forced_public_reading',true,'no_forced_prayer',true,'no_forced_recitation',true,'no_forced_ritual',true,'no_sacred_practice_simulation',true,'no_sacred_object_handling',true,'documentary_analysis_only',true,'neutral_equivalent_activity',true,'opt_out_without_penalty',true,'non_confessional',true,'no_belief_disclosure',true,'no_nonbelief_disclosure',true,'no_family_religion_disclosure',true,'no_personal_sacred_text_request',true,'no_worship_place_disclosure',true,'no_personal_experience_request',true,'privacy_preserving',true,'compare_provided_materials_only',true,'no_belief_hierarchy',true,'myth_is_not_lie',true,'science_religion_method_distinction',true,'internal_diversity',true,'community_authority',true,'no_identity_impersonation',true,'brief_authorized_excerpts',true,'copyright_respect',true,'mobility_vision_hearing_inclusive',true,'print','grayscale-safe'),true,true,true,'published','/escola-brilha/curso-v4/ensino-religioso-6ano/'||lower(code) FROM lessons
ON CONFLICT (source_lesson_key,codigo_bncc) DO UPDATE SET source_version=EXCLUDED.source_version,title=EXCLUDED.title,school_stage=EXCLUDED.school_stage,school_year=EXCLUDED.school_year,subject=EXCLUDED.subject,knowledge_object=EXCLUDED.knowledge_object,learning_goal=EXCLUDED.learning_goal,supported_profiles=EXCLUDED.supported_profiles,teacher_pages=EXCLUDED.teacher_pages,student_pages=EXCLUDED.student_pages,answer_key=EXCLUDED.answer_key,accessibility=EXCLUDED.accessibility,source_fidelity_checked=EXCLUDED.source_fidelity_checked,pedagogical_reviewed=EXCLUDED.pedagogical_reviewed,technical_reviewed=EXCLUDED.technical_reviewed,status=EXCLUDED.status,source_route=EXCLUDED.source_route,updated_at=now();
-- Biblioteca Inclusiva · Ensino Religioso do 7º ano completo.
-- O curso ativo zera os códigos das sete aulas antigas e concentra EF07ER01–08 nas oficinas BNCC.
WITH lessons(code,title,goal) AS (VALUES
('EF07ER01','Práticas de comunicação com divindades','Reconhecer práticas de comunicação com divindades em diferentes tradições por análise contextual, sem participação devocional.'),
('EF07ER02','Espiritualidade em situações específicas','Identificar práticas de espiritualidade usadas por algumas pessoas em situações específicas, preservando autonomia e distinguindo apoio espiritual de serviços profissionais.'),
('EF07ER03','Papéis das lideranças religiosas','Reconhecer papéis atribuídos a lideranças religiosas conforme cada tradição, sem tratá-las como representantes absolutos de grupos diversos.'),
('EF07ER04','Contribuições sociais de lideranças','Exemplificar contribuições sociais verificáveis de lideranças religiosas em diferentes tempos e espaços, analisando fontes, contexto, efeitos e limites.'),
('EF07ER05','Estratégias de convivência ética','Discutir estratégias que promovam convivência ética entre religiões, filosofias de vida e pessoas sem religião, com direitos, diálogo e limites.'),
('EF07ER06','Princípios éticos e práticas sociais','Identificar princípios éticos em tradições religiosas e filosofias de vida e relacioná-los criticamente a condutas e práticas sociais.'),
('EF07ER07','Lideranças e direitos humanos','Discutir o papel de lideranças religiosas e seculares na defesa e promoção dos direitos humanos com base em ações e fontes verificáveis.'),
('EF07ER08','Liberdade de consciência, crença e convicção','Reconhecer o direito de ter, mudar ou não ter religião ou convicção e questionar coerção e discriminação sem exigir relato pessoal.')
), normalized AS (
 SELECT code,'src/escola-brilha/curso-v4/ensino-religioso-7ano/oficinas-bncc.ts'::text AS source_key,title,goal FROM lessons
)
INSERT INTO public.teacher_inclusive_lessons (source_lesson_key,source_version,codigo_bncc,title,school_stage,school_year,subject,knowledge_object,learning_goal,supported_profiles,teacher_pages,student_pages,answer_key,accessibility,source_fidelity_checked,pedagogical_reviewed,technical_reviewed,status,source_route)
SELECT source_key,'audit-2026-09-04',code,title,'fundamental_2','7º Ano','Ensino Religioso',title,goal,ARRAY['tea','tdah','dislexia','deficiencia_intelectual','comunicacao','motora_escrita','sensorial_auditiva','sensorial_visual'],
jsonb_build_array(jsonb_build_object('title','Guia inclusivo de Ensino Religioso — '||code,'purpose',goal,'sections',jsonb_build_array(
 jsonb_build_object('heading','Abordagem não confessional','content',jsonb_build_array('Apresente religião, espiritualidade, filosofia de vida, liderança, ética e direitos como objetos de estudo; conhecer não significa acreditar, concordar, aderir ou praticar.','Não conduza oração, meditação religiosa, canto, recitação, oferenda, rito, gesto, dança, dramatização, aconselhamento espiritual ou simulação de situação vulnerável. Use casos fictícios e análise documental.','Não peça crença, ausência de crença, mudança de religião, prática familiar, liderança frequentada, experiência difícil, opinião íntima ou posicionamento público. Sempre aceite alternativa neutra e recusa sem prejuízo.')),
 jsonb_build_object('heading','Direitos, segurança e serviços','content',jsonb_build_array('Ensine liberdade de consciência como direito de ter, mudar ou não ter religião ou convicção, dentro do respeito aos direitos das outras pessoas.','Em casos de discriminação, priorize interromper a conduta, proteger a pessoa afetada, registrar pelos canais institucionais e acionar responsáveis e rede de proteção conforme o protocolo escolar; não obrigue confronto, mediação ou reconciliação.','Apoio religioso ou espiritual pode coexistir com cuidado profissional, mas não substitui saúde, emergência, proteção civil, assistência social ou políticas públicas. O professor não diagnostica nem recomenda prática religiosa.')),
 jsonb_build_object('heading','Investigação crítica e acessível','content',jsonb_build_array('Pesquise contribuições e controvérsias por ações, datas, contexto, fontes confiáveis e efeitos; não use número de seguidores, fama ou identidade religiosa como prova de mérito.','Reconheça diversidade interna, lideranças religiosas e seculares, filosofias de vida e pessoas sem religião. Evite generalizar, hierarquizar ou transformar uma liderança em porta-voz total.','Ofereça texto segmentado, glossário visual, legenda, transcrição, descrição de imagem, áudio regulável, casos fictícios, cartões e organizadores; aceite comunicação alternativa, seleção, escrita, digitação, fala opcional ou áudio privado.')),
 jsonb_build_object('heading','Critério','content','Analisa quatro de cinco elementos da habilidade com direito aplicável, evidência, contexto, efeito e proposta segura, no modo acessível escolhido.')))),
jsonb_build_array(jsonb_build_object('title','1. Identificar o caso','instruction','Leia um caso fictício e identifique prática, pessoas envolvidas, direito, papel de liderança e serviço profissional quando pertinente.','activity','Classifique cartões de fato, interpretação, direito, apoio e ação segura sobre '||lower(title)||'.','support','Leitura fácil, texto segmentado, glossário visual, fonte ampliada, áudio regulável, legenda, transcrição e descrição de imagem.'),jsonb_build_object('title','2. Verificar fontes e efeitos','instruction','Compare duas fontes, separe afirmação de evidência e reconheça diversidade interna e limites.','activity','Complete quadro com autoria, data, contexto, ação, efeito, direito e informação ainda necessária.','support','Modelo resolvido, cartões móveis, pistas graduadas, código por forma e rótulo, tempo ampliado e mediação.'),jsonb_build_object('title','3. Propor resposta ética','instruction','Escolha uma resposta que preserve autonomia, dignidade, segurança, direitos e serviços adequados.','activity','Monte sequência de ação para caso fictício, sem revelar crença ou experiência pessoal e sem apresentação pública obrigatória.','support','Apontar, selecionar, comunicação alternativa, mapa, digitação, escrita, fala opcional, áudio privado ou tecnologia assistiva.')),
jsonb_build_array(jsonb_build_object('page',1,'answer','Identifica fato, direito e papel sem presumir crença, intenção ou identidade.'),jsonb_build_object('page',2,'answer','Usa fonte e contexto para avaliar ação, efeito, contribuição ou limite sem generalização.'),jsonb_build_object('page',3,'answer','Propõe resposta que protege autonomia e direitos e encaminha ao serviço adequado quando necessário.','teacher_note','Registre estratégia e apoio eficaz; não registre religião, não religião, mudança de crença, voz, experiência difícil, opinião ou vínculo comunitário.')),
