-- Biblioteca Inclusiva · Ensino Religioso do 8º ano completo (EF08ER01–EF08ER07).
-- A BNCC oficial inclui EF08ER07; a aula antiga da unidade 6 tem o código EF08ER06 desativado pelo curso.
WITH lessons(code,source_key,title,goal) AS (VALUES
('EF08ER01','src/escola-brilha/curso-v4/ensino-religioso-8ano/unidade-1/aula-01-crencas-escolhas.ts','Crenças, convicções e escolhas','Discutir como crenças e convicções podem influenciar escolhas pessoais e coletivas sem solicitar posicionamento íntimo do estudante.'),
('EF08ER02','src/escola-brilha/curso-v4/ensino-religioso-8ano/unidade-2/aula-01-etica-tradicoes.ts','Princípios éticos das tradições e filosofias','Analisar filosofias de vida, manifestações e tradições religiosas, destacando princípios éticos com contexto e diversidade interna.'),
('EF08ER03','src/escola-brilha/curso-v4/ensino-religioso-8ano/unidade-3/aula-01-vida-e-morte.ts','Concepções de mundo, vida e morte','Analisar concepções de mundo, vida e morte em diferentes doutrinas de modo informativo, não gráfico e sem relatos pessoais.'),
('EF08ER04','src/escola-brilha/curso-v4/ensino-religioso-8ano/unidade-4/aula-01-religiao-esfera-publica.ts','Religião e esfera pública','Discutir como filosofias, tradições e instituições religiosas podem influenciar política, saúde, educação e economia usando fontes e casos coletivos.'),
('EF08ER05','src/escola-brilha/curso-v4/ensino-religioso-8ano/unidade-5/aula-01-estado-laico.ts','Possibilidades e limites na esfera pública','Debater possibilidades e limites da atuação de tradições religiosas na esfera pública à luz do Estado laico, dos direitos e da igualdade.'),
('EF08ER06','src/escola-brilha/curso-v4/ensino-religioso-8ano/unidade-5/aula-02-liberdade-politicas-publicas.ts','Liberdade em práticas, projetos e políticas','Analisar práticas, projetos e políticas públicas que promovam liberdade de pensamento, crença e convicção com evidências verificáveis.'),
('EF08ER07','src/escola-brilha/curso-v4/ensino-religioso-8ano/unidade-7/aula-01-transmissao-tradicoes.ts','Religiões, mídias e tecnologias','Analisar usos de mídias e tecnologias por diferentes denominações religiosas, considerando finalidade, autoria, alcance, privacidade e segurança digital.')
)
